sources=[dict(id='PEP-G5-U',path='research/source-textbooks/grade-5/义务教育教科书数学五年级上册.pdf',pdfPages=126,edition='人民教育出版社；目录为“观察简单组合体”开篇的版本；版权页未提供可确认的版次年份',printedPageOffset=6),dict(id='PEP-G5-L',path='research/source-textbooks/grade-5/义务教育教科书 数学 五年级下册.pdf',pdfPages=132,edition='人民教育出版社；目录为“观察物体（三）”开篇的版本；版权页未提供可确认的版次年份',printedPageOffset=6)]
units=[]; lessons=[]
def unit(code,title,pages,notes=''):
    units.append(dict(id='G5-'+code,term='上册' if code.startswith('U') else '下册',title=title,sourceId='PEP-G5-'+code[0],printedPages=pages,coverage=[],sequence=[],notes=notes))
def add(code,title,pages,prior,goal,problem,why,model,steps,example,practice,error,retell,next_,note=''):
    uid='G5-'+code.split('-')[0]; tier=code.split('-')[1][0]; u=next(x for x in units if x['id']==uid)
    pnums=pages.replace('–','-').split('-'); pdf='–'.join(str(int(p)+6) for p in pnums)
    levels=['基础','基础','变式','迁移','挑战','回顾']; tasks=[]
    for i,line in enumerate(practice):
        q,a,r=line.split('|'); tasks.append(dict(level=levels[i],question=q,answer=a,reason=r))
    q,es,a=example
    item=dict(id='G5-'+code,title=title,unitId=uid,tier=tier,minutes=35,anchor=dict(sourceId=u['sourceId'],printedPages=pages,pdfPages=pdf,type='extension' if tier in ['E','O'] or uid=='G5-U10' else 'textbook',note=note or ('本课为所列教材内容上的原创提升；不是另一个课本单元。' if tier in ['E','O'] else '页码为已核实的教材锚点；例题、练习重新编写。')),prerequisites=prior.split('；'),dependsOn=[],objective=goal,realProblem=problem,why=why,model=model,explanation=steps.split('；'),example=dict(question=q,steps=es.split('；'),answer=a),practice=tasks,misconception=dict(wrong=error[0],correction=error[1]),retell=retell,next=next_)
    lessons.append(item);u['sequence'].append(item['id']);u['coverage'].append(dict(topic=title,lessonIds=[item['id']]))

unit('U01','观察简单组合体','1–6','本版上册与下册第一单元重合；本处主教三个方向的观察，下册只做诊断与条件推理。')
add('U01-B01','同一堆积木，为什么会有三张不同的图？','1','认识正方体；前后左右上下面','把立体按方向转成平面格图，区分遮挡与缺失。','给不能走到桌旁的朋友画积木搭法，只画正面够不够？','同一视线上的积木会互相遮挡，平面图只记录这个方向能看到的轮廓。','底层从左到右摆三块，左端上方再叠一块；所有块只有一排深。','固定观察方向，不边看边转积木；从前面逐列记录高度2、1、1；从上面看到一排3格，从左面看到竖着2格。',('同样的搭法共用几块？三幅图的格数为什么不都等于积木数？','底层3块加上层1块共4块；正面4格、上面3格、左面2格；顶视和侧视都有遮挡。','4块，格数取决于观察方向。'),['一排摆4块，从上面见几格？|4格|每块占一个不同位置。','竖叠4块，从上面见几格？|1格|四块在同一视线上。','竖叠4块从前面见几格？|4格|高度方向没有遮挡。','两排两列各高1块，从前面见几格？|2格|后排被前排遮住。','正面见3格，就一定只有3块吗？举例。|不一定；一排3块后面再放1块|后面的块可能被遮住。','例题左端再向上加1块，上视图变吗？|不变|增加的是高度，不增加占地位置。'],('看到几个格，就一定有几块积木。','格图记录可见轮廓，不直接给出总块数。'),'为什么从上面看不到底层被盖住的积木？','下一课利用多个方向的图约束搭法。')
add('U01-E01','凭一张图不能确定：补什么信息才有用？','1','三方向观察','用反例解释信息不足，逐条筛选可能搭法。','朋友只说正面是两列各高1块，我们能还原积木吗？','新信息应排除不符合条件的方案；找出两个不同方案就能证明“不唯一”。','方案甲一排2块；方案乙两排两列4块，均只有一层。','分别画两方案正面，都是横着2格；比较上视图，甲2格而乙4格；增加“上面是2×2格”便排除甲，但仍需高度条件。',('正面两列各1格，上面2×2格，全部只有一层，共几块？','上视图要求占4个位置；一层要求每处1块；合计4块。','4块。'),['正面1格能否排除竖叠2块？|能|竖叠2块正面应有2格。','正面1格能否排除前后放2块？|不能|前块遮住后块。','只有上视图能知道高度吗？|不能|同一占地可以有不同高度。','一层积木上面看L形3格，共几块？|3块|每个占地只有1块。','“正面横2格且上面横2格”还需约定什么？|方向一致、积木按方格摆且不悬空|条件清楚才可约束搭法。','写一句比“像小楼”更精确的搭法。|例如底层横排3块，中间上叠1块|给出位置和层数。'],('三张图总能唯一还原任何立体。','三张轮廓也可能不足；本课只判断已给条件下的具体搭法。'),'证明“不唯一”时为什么两个例子就够？','下册观察单元只检验本课并增加上下界，不重讲三幅图。')

unit('U02','小数乘法','7–23','整数运算律只复习其意义；本章教学增量是计算单位和小数倍，不重新当作新定律教。')
add('U02-B01','同样价格买几份：小数乘整数','7–8','整数乘法；小数计数单位','把小数看作若干个0.1或0.01，解释积的小数点。','一段装饰绳长1.25米，做4段需要多少米？','计数单位不变，份数增加；125个百分之一的4倍仍是百分之一。','画1米长纸带，每米分100小格，4条各取125格。','1.25米是125个0.01米；125×4=500个0.01米；500个0.01米是5米，末尾0可省略。',('每支笔2.4元，买6支付多少？','24角×6=144角；144角=14.4元；用2×6与3×6估计，答案在12与18元之间。','14.4元。'),['0.7×8是多少？|5.6|7个0.1乘8是56个0.1。','1.08×5是多少？|5.4|108个0.01乘5得540个0.01。','有人算0.6×4=24，哪里错？|把0.1当成了1|24个0.1是2.4。','每天走1.2千米，5天共走多远？|6千米|5份1.2。','不用竖式算0.125×8。|1|125×8=1000，再除1000。','小数乘整数与重复加法有什么联系？|整数份数时可以反复加同一个小数|乘法缩写等量合并。'],('乘出来有整数0，就全部删掉。','只能删小数部分末尾的0，不能改变数位。'),'为什么1.08×5的整数乘积540要缩小100倍？','转向两因数都是小数，两个缩放都要补偿。')
add('U02-B02','两个数都缩放：小数乘小数','10','小数乘整数；面积计数','理解积的小数位数由两个因数的计数单位共同决定。','一块小垫长0.6米、宽0.4米，面积会不会超过1平方米？','十分之一乘十分之一得到百分之一；不能沿用加法的小数点对齐规则。','1米见方格纸分成10×10小格，圈出6列4行。','圈出的24格各是0.01平方米；0.6×0.4=0.24；一般先转为整数乘，再按两个放大倍数还原。',('求0.12×0.3。','12×3=36；因数分别放大100和10倍，积放大1000倍；36÷1000=0.036。','0.036。'),['0.4×0.2是多少？|0.08|8个百分之一。','0.03×0.5是多少？|0.015|15除以1000。','0.2×0.2=0.4对吗？|不对，应为0.04|混用了加法结果。','长1.2米宽0.5米，面积多少？|0.6平方米|半个1.2平方米。','0.05×0.04为何需要补0？|20÷10000=0.002|整数积位数不足，仍需还原四位。','1.20×0.5写成0.60与0.6矛盾吗？|不矛盾|小数末尾0不改变大小。'],('乘法像加法一样先把小数点上下对齐。','乘法按数位计算后根据因数缩放确定积，不是同单位直接相加。'),'用方格说说0.6×0.4为什么不是2.4？','下一课解释0.8倍与1.2倍为什么一个变小一个变大。')
add('U02-B03','0.8倍是什么意思？乘法不一定变大','14–15','小数乘法；倍数比较','把非整数倍理解为以原量为1倍进行缩放。','一张原图长10厘米，打印为0.8倍和1.2倍，各有多长？','倍数描述与原量的关系，0.8倍是原量的八个十分之一。','原长度条分10等份，0.8倍取8份，1.2倍取12份。','先固定原量为1倍；小于1的正倍数只取部分原量，大于1的倍数超过原量；比较积与原量时说明原量是正数。',('原绳长7.5米，新绳是它的0.6倍，新绳多长？','7.5÷10=0.75；取6份得4.5；4.5小于7.5，符合少于1倍。','4.5米。'),['12的0.5倍是多少？|6|取一半。','8的1.25倍是多少？|10|8×1.25。','正数a乘0.9，积与a相比？|小于a|只取九成的原量。','照片宽4厘米，放大1.5倍后宽多少？|6厘米|4×1.5。','“乘大于1的数，积必定变大”遗漏什么条件？|原数须为正数；0不会变大|比较需限定原量。','0.4×1与0.4×0有何不同？|0.4与0|1倍保持，0倍为0。'],('乘法一定使数变大。','正数乘正数时要比较乘数与1；本课不讨论负数乘法。'),'0.6倍不是“减去0.6”，你能用7.5米说明吗？','衔接六年级分数乘法的几分之几倍。')
add('U02-E01','运算律迁移到小数：先认结构再简算','15','整数交换、结合、分配律；小数乘法','分清交换次序、重新分组与拆分一因数，选有依据的简算。','购买8份0.25千克材料，再加8份0.75千克，如何一眼看清总量？','同样的份数可以先合并每份的量；运算律依赖数量结构而非数字写法。','8个袋子，每袋放0.25与0.75两段色条。','0.25×8+0.75×8可合为(0.25+0.75)×8；0.25×7×4是换序并结合成0.25×4；0.6×(10+2)要把0.6分别乘两项。',('简算2.5×3.6+2.5×6.4。','两项都有2.5；提成2.5×(3.6+6.4)；2.5×10=25。','25。'),['0.125×7×8简算。|7|先合0.125×8=1。','4.8×101简算。|484.8|4.8×100+4.8。','0.3×(2+5)=0.3×2+5对吗？|错，应为2.1|5也要乘0.3。','每份茶点2.6元、饮料1.4元，9份共多少？|36元|(2.6+1.4)×9。','7.2÷(0.3+0.6)能拆成7.2÷0.3+7.2÷0.6吗？|不能；8不等于36|除数不能这样分配。','0.5×(6×2)改成(0.5×6)×2用了哪条律？|乘法结合律|只改分组，不改顺序。'],('只要有括号就能去掉。','先判断外层运算；等值变形必须有对应定律。'),'两项都含2.5时，为什么可以把它拿到括号外？','在小数除法与字母表达中迁移这些结构，不另起重复简算课。')
add('U02-B04','预算与分段收费：题目规定怎样算钱？','18–19','小数乘加；估算；进一取整的直观','区分估算够不够和精算付多少，读清起步段与超出段。','租车前三小时共18元，超过部分每小时4.5元，不足1小时按1小时计。用4.2小时付多少？','前一段不是每小时18元；不足整段怎样收费由规则决定。','时间线标0、3、4、5小时；3小时前涂同一颜色。','先将总时间分为3小时与超出1.2小时；超出段按2小时收费；18+2×4.5=27，不能直接4.2×4.5。',('同一规则，用3小时、3.1小时分别付多少？','3小时没有超出段；3.1小时超出0.1，按1小时；分别18与18+4.5。','18元、22.5元。'),['每盒彩泥9.8元，买5盒，50元够吗？|够|9.8<10，5盒少于50。','按租车规则用2小时付多少？|18元|前三小时共18元。','用5小时付多少？|27元|超出2小时。','用5.1小时付多少？|31.5元|超出2.1，计3小时。','“9.8约10，所以必须付50元”对吗？|错，实付49元|估算用于判断，不替代约定价格。','为什么4.2小时不能四舍五入成4小时计费？|规则指定不足1小时按1小时|情境规则决定取整。'],('所有近似都按四舍五入。','预算、测量、计费各有任务要求，需先读规则。'),'为什么只对“超出段”向上取整？','单元复盘：乘法算等份总量；分段情境先画结构再列式。')

unit('U03','小数除法','24–38')
add('U03-B01','余下的1还能继续分：除数是整数','24–25','整数除法；小数单位','解释添0继续除与商0占位。','3米彩带平均分给4人，每人不足1米，该怎样写？','1可换成10个0.1；余数不是不能分，而是换更小的计数单位。','三条1米带分别十等分，再将每条小段细分十分。','3÷4整数部分为0；30个0.1分4人，每人7个0.1余2个0.1；20个0.01再分，每人5个，合0.75。',('5.4升果汁均分6瓶，每瓶多少？','54个0.1升均分6份得9个0.1升；写0.9；0.9×6=5.4验算。','0.9升。'),['8.4÷4是多少？|2.1|84个0.1除以4。','0.63÷7是多少？|0.09|63个0.01分7份。','2÷5是多少？|0.4|20个0.1均分5份。','3.6米剪成8段，每段多长？|0.45米|36个0.1继续细分。','0.63÷7=0.9错在哪？|商的计数单位错；应0.09|9个0.01不是9个0.1。','5.4末尾添0为什么没多添果汁？|5.40与5.4相等|只换更细单位表示。'],('除完整数有余数就停止。','可以换更小单位继续分；若题目只取完整物件另按情境判断。'),'商整数部分的0为什么不能漏？','下一课观察除不尽时余数怎样重复。')
add('U03-B02','为什么有的除法算不完：循环小数与近似','27','小数除以整数；余数','用重复余数解释循环，不把有限显示当精确值。','1米纸带分3份，用小数究竟要写几个3？','同一余数重新出现，之后的除法过程相同，所以商的数字重复。','记录1÷3每一步：10÷3得3余1；余1再次换成10个下一单位。','余数1不断重复，商为0.333…；省略号表示一直继续，不能写等于0.33；需要到百分位时看第三位，约为0.33。',('5÷6的商保留两位小数。','50÷6得8余2；20÷6得3余2，3开始循环；0.833…看第三位3，约0.83。','5÷6=0.833…≈0.83。'),['1÷8是有限小数吗？|是，0.125|除到余数0停止。','2÷3保留两位小数。|0.67|第三位6，向前进1。','0.272727…的循环节是什么？|27|反复出现的最短数字组。','计算器显示0.1666667，可以断定原商精确等于它吗？|不能|显示位数有限，可能已取近似。','0.333…与0.33谁大？|0.333…大|第三位分别3与0。','循环小数与小数位数很多的有限小数有何区别？|前者无限重复，后者最终结束|不是按眼前位数多少区分。'],('循环小数就是随意把后面数字省掉。','循环写法需说明无限重复；近似值用约等号。'),'为什么同一个余数会带来同一串后续数字？','下册分数与小数互化会解释同一商的另一种精确表示。')
add('U03-B03','把除数变整数，为什么两边都要动？','31–32','商不变规律；小数除整数','通过同单位换算理解小数除法，不只记移动小数点。','4.2米绳子，每0.6米剪一段，能剪几段？','总长度和每段长度用同一新单位表示，段数不变。','把4.2米与0.6米都改成分米：42分米与6分米。','4.2÷0.6=42÷6；两数同时乘10保持商不变；只放大一个数就改变每组或总量，商会改变。',('求3.6÷0.24。','除数乘100变24；被除数同乘100变360；360÷24=15，15×0.24=3.6。','15。'),['6.3÷0.7是多少？|9|同乘10成为63÷7。','1.2÷0.03是多少？|40|同乘100成为120÷3。','2.4÷0.6改为24÷0.6行吗？|不行|只改了被除数，商变10倍。','5.5千克每袋0.25千克，装几袋？|22袋|550÷25。','4÷0.08为什么写成400÷8？|两数同乘100|4写成4.00后移动两位。','除数能是0吗？|不能|除以0没有确定商。'],('除数有两位小数，被除数不够就少移一点。','必须同时乘相同的非零倍数；位数不够添0补齐。'),'把米改成厘米时，段数为什么不变？','下一课区分除以0.5与乘0.5的实际意义。')
add('U03-E01','除以0.5为何变大：按组大小比较商','32–34','小数除法；倍数关系','把除法中的平均分与包含联系到商的大小。','6升水装入0.5升瓶与1.5升瓶，哪种瓶装得更多？','总量固定，每份越小，可容纳的份数越多。','6个1升格，每格切成两半，数得12个半升。','6÷0.5问含几个半升，得12；6÷1.5问含几个一点五升，得4；正数除以0到1之间的数商大于原数，但除以1保持。',('比较7.2÷0.8与7.2，不做竖式也能判断吗？','0.8比1小，同样总量分成更小份；份数大于7.2；算得9验证。','7.2÷0.8=9>7.2。'),['10÷0.5是多少？|20|每个1含两个0.5。','10×0.5是多少？|5|取10的一半。','正数a÷1.2与a相比？|较小|每组大于1。','3升水装0.2升杯，几杯？|15杯|每升5杯。','“除法使数变小”用一个例子推翻。|如2÷0.5=4|按更小单位计数。','0÷0.5等于多少？|0|总量0，没有一份。'],('除以0.5就是把它减半。','除以0.5求半个单位的个数；乘0.5才是取一半。'),'用装瓶解释同一个6为何除以0.5得到12。','六年级分数除法从单位份数延伸，不再机械背“除法变小”。')
add('U03-B04','装满几瓶与至少几瓶，是两个问题','35','小数除法；近似数','根据能完成的整份与容纳全部两种目标处理商。','5升饮料，每瓶装0.8升：能装满几瓶？全部装下至少准备几瓶？','同一个商6.25描述6个满瓶和一部分；问题决定是否保留余量对应的瓶子。','画6个0.8升满瓶，剩0.2升另画第7个不满瓶。','5÷0.8=6.25；能装满6瓶且余0.2升；全部装下需7瓶，不把6.25四舍五入成6瓶。',('4.6米绳每份0.7米，完整做几份？剩多少？','4.6÷0.7=6.571…；完整份取6；剩4.6-0.7×6=0.4米。','6份，剩0.4米。'),['9千克每袋2千克，装满几袋？|4袋|只能取完整份。','9千克每袋最多2千克，至少几袋？|5袋|余1千克也需袋。','9÷2=4.5，两个问题都答5合理吗？|不合理|“装满”不能包含半袋。','8元钱买1.5元一支的笔，最多几支？|5支|6支需9元，钱不够。','4.6÷0.7剩的0.4能直接读成商小数部分吗？|不能|余长须用总长减已用长。','均分1米给3人，每人保留两位小数与剪完整段一样吗？|不同|前者近似长度，后者计整份。'],('商后小数部分就是剩余长度。','商的小数部分单位是份；剩余原量要乘除数或用减法算。'),'为什么同一算式有时答6，有时答7？','本章复盘时同时核对计算正确与情境回答正确。')
add('U03-O01','先求每一份：归一与双向检查','29','小数乘除；总量与份数','识别归一思想，比较总量不同的方案而不盲比总价。','甲店3米彩带9.6元，乙店5米15.5元，哪家每米便宜？','比较需要共同标准，把各自总价还原到1米才公平。','两条不同长度价签，分别画成每米一格。','甲每米9.6÷3=3.2元；乙每米15.5÷5=3.1元；比较每米价格，若买2米分别6.4和6.2再验证。',('机器2.5小时做35个零件，按相同速度4小时做多少？','每小时35÷2.5=14个；4小时14×4=56个；4小时比2.5小时多，数量应增加。','56个。'),['6本共19.2元，每本多少？|3.2元|总价除本数。','同价笔4支10元，7支多少？|17.5元|先10÷4，再乘7。','2千克12元比5千克25元便宜吗？|每千克反而贵|6元/千克比5元/千克贵。','同速走1.5小时6千米，2小时多远？|8千米|每小时4千米。','“买得多一定便宜”能直接判断吗？|不能|须知道单价或折扣规则。','归一后的乘回检查是什么？|单价×原份数应等于原总量|可发现单位或关系错误。'],('所有成倍问题都可按同一速度或单价推算。','必须确认单位量不变；分段收费等情境不适用。'),'为什么比较彩带时先算1米有用？','归一作为方法索引，后续分数、比和比例使用时标“迁移”。')

unit('U04','图形的运动','39–54','含轴对称、平移、旋转及运动解决面积；下册旋转采用诊断迁移，避免再教一遍。')
add('U04-B01','对称不是“差不多像”：对应点与等距离','39','对称轴初步；数格','用垂直距离相等补全轴对称图形。','设计蝴蝶徽章，右半边怎样准确复制左半边？','轴对称把每个点翻到对称轴另一边，距离保持，方向相反。','竖直对称轴左侧3格画点A；在同一横线上右侧3格画A′。','选顶点并找到其与轴的垂直方向；逐点数到轴的格数，在另一侧等距标点；连接对应顶点，折叠检验。',('点P在竖直轴左2格、点Q在轴上，翻折后位置怎样？','P沿水平线到右2格；Q到轴距离0，保持原位；不是把整图平移4格。','P到右2格，Q不动。'),['点在轴左5格，对称点在哪？|同一横线轴右5格|到竖直轴等距。','轴上的点会去哪？|原处|距离轴为0。','左1格的点翻到右2格对吗？|不对|两侧距离不等。','沿水平轴翻折，点原在上方3格？|到正下方3格|垂直于水平轴移动。','所有对称点连线长度相同吗？|不一定|离轴距离可以不同。','画对称图为什么先找顶点？|顶点确定边的位置|连线即可还原多边形。'],('数格沿着斜边量。','距离对称轴指垂直距离，不是任意斜线长。'),'轴上的点为什么不用移动？','平移与旋转比较：三种运动都保形，但点的移动规则不同。')
add('U04-B02','平移与旋转：要把指令说完整','43–47','数格；直角；平移初步','描述方向距离，或中心方向角度，并保持对应长度。','把地图上的三角形旗移到新位置，怎样让别人照指令画对？','“移过去”“转一下”信息不足；不同中心或方向会得到不同位置。','方格纸上点O右3格有A；以O为轴逆时针转90°，A到O上3格。','平移让每点同方向同距离，图形朝向不变；旋转先固定中心，再定方向和角；对应点到中心的距离保持不变。',('点A在O上2格，绕O顺时针转90°后在哪里？','从向上转向右；仍离O2格；标在O右2格。','O右2格。'),['平移“向右4格”，每个顶点移几格？|4格|整个图共同移动。','点在O右1格，逆时针90°后在哪？|O上1格|保持半径。','旋转中心自己移动吗？|不移动|中心到自身距离0。','向右2格再向右3格等于什么？|向右5格|同向距离相加。','同中心顺时针90°再90°等于多少？|顺时针180°|角度相加。','只说“转90°”缺什么？|中心和方向|它们决定最终位置。'],('旋转后离中心更远，看起来才像转过了。','旋转保持每点到中心的距离。'),'为什么平移不能改变旗子的朝向？','下课用运动把不好计算的面积转成熟悉图形。')
add('U04-E01','移动不添不减：剪拼面积为什么保持？','43','平移；长方形面积','把移动图块与面积不变联系，明确无重叠无遗漏。','一张6×4厘米纸片左侧挖下一块，又把同一块贴到右侧，总面积改了吗？','面积数覆盖的单位方格，搬动本身不产生或损失面积。','画6×4长方形；左边剪下1×2小块，平移到右边空处且不重叠。','原面积24；剪下后剩22，另有2仍保留；重新拼合22+2=24，须检查未压叠也未丢弃。',('5×3方纸剪下1×2小块放到外侧，组成新图，面积多少？','原面积15；剩13和剪块2；无重叠拼回为15。','15平方厘米。'),['原面积20，剪成两块后两块总面积多少？|20|切割不删去纸。','两块分别6和4，重叠1后外轮廓覆盖多少？|9|6+4-1。','“只要拼在一起面积就直接相加”对吗？|需无重叠|重叠区域不能重复算。','8×3长方形移动一块后面积？|24平方厘米|无丢失无重叠。','剪拼后周长一定不变吗？|不一定|外露边界可能改变。','本课与平移的联系是什么？|用平移重排图块以转成熟悉图形|移动是求面积的方法。'],('面积不变，周长也不变。','面积记录内部大小，周长记录新外边界，两者不同。'),'保持面积的两个检查条件是什么？','接入平行四边形、三角形、梯形公式的推导。')

unit('U05','用字母表示数和数量关系','55–71','本册是字母与数量关系，未列“简易方程”单元。等式与方程另设U10混版桥接，明确非此PDF原章。')
add('U05-B01','数字还不知道，也能写出关系','55','加减倍数关系','用字母记录会变化的量，表达同一关系。','Kevin比妹妹大4岁，妹妹年龄变化时要重写多少条加法？','字母让一条表达式适用于多种可能数值，但其范围要符合情境。','表格列妹妹年龄3、4、5，对应Kevin7、8、9，末行写a与a+4。','先定义a代表妹妹年龄；a+4表示Kevin年龄；代入某个a可算具体年龄，a本身并不总等于1。',('妹妹a岁，妈妈比妹妹大28岁，用式子表达；a=9时呢？','定义年龄单位为岁；妈妈年龄a+28；代入9+28=37。','a+28岁；37岁。'),['n个苹果又放入3个，现有多少？|n+3个|原有量加新增量。','一本书p元，买4本多少？|4p元|4份同价。','a+5能写成5a吗？|不能|前者加5，后者乘5。','两箱共20个，一箱x个，另一箱？|20-x个|整体减一部分。','20-x的情境中x能为30吗？|不能|这里x是0至20的整数。','字母由a改成t，关系会变吗？|不会，只要定义一致|名字不是数量关系本身。'],('字母只是某一个固定数字的代号。','它可以表示未知的确定值，也可以表示允许范围内变化的值；需看任务。'),'为什么写a+4前必须说明a是谁的年龄？','下一课用字母写公式与运算律；再进入方程桥接。')
add('U05-B02','公式是关系的缩写：求值与书写','58','字母表达；面积周长公式','区分2a与a²，理解省略乘号和代入求值。','同样的正方形越来越大，边长改了，面积关系需要重写吗？','公式保留结构，让输入尺寸改变而计算规则不变。','画边长a的正方形；一边标a，一行a个单位格，共a行。','a×a写a²，2×a写2a；面积S=a²，周长C=4a；求值是把每个a换成同一数再按顺序算。',('边长1.5厘米，求正方形面积和周长。','S=1.5×1.5=2.25；C=4×1.5=6；两个结果分别描述覆盖与边界。','面积2.25平方厘米，周长6厘米。'),['a=3时2a是多少？|6|2×3。','a=3时a²是多少？|9|3×3。','a×1可简写什么？|a|乘1不改变。','速度v、时间t，匀速路程怎样写？|s=vt|路程是速度乘时间。','a=2时2a=a²，能证明始终相等吗？|不能；a=3时6≠9|一个巧合值不是一般规律。','2+3能把加号省略成23吗？|不能|省略规则只针对合适的乘法表达。'],('a²就是a×2。','指数2表示两个a相乘，不是2份a相加。'),'为什么a=3时是检查2a与a²的好例子？','将四年级运算律用字母统一表述，并用于解释规律。')
add('U05-E01','同一关系的两种写法：合并与展开','64','字母表达；分配律','把数字简算提升为等值表达，解释括号的范围。','每盒有红笔a支蓝笔b支，5盒共多少支？','先合每盒或分颜色统计得到同一总量，因此5(a+b)=5a+5b。','画5行，每行左a个右b个，用框分别圈每行和各颜色。','5作用于括号里的整个和；5a+5b是分开统计后相加；反向合为5(a+b)，不是把a和b当同一种量合并成2a。',('每袋有x颗糖，3袋再加2袋共多少？如果再添2颗呢？','3x+2x=5x；3袋再添2颗是3x+2；给x=4检验分别20和14。','5x；3x+2。'),['6a+4a化简。|10a|同一个a共10份。','4(x+2)展开。|4x+8|4分别乘x和2。','3a+3b能变成6ab吗？|不能|加两种量不是相乘。','每小时走v千米，上下午分别a、b小时，总路程？|v(a+b)|速度相同才可这样合。','7(x-2)展开并说条件。|7x-14；本课x≥2|分配律用于差，情境量保持非负。','3x+2x与3(x+2)差在哪？|前者5份x，后者3份x再加6|括号范围不同。'],('4(x+2)=4x+2。','整份括号被乘4，常数2也要重复4次。'),'画5盒笔，讲出为什么两种式子一定相等。','桥接方程中的合并同类量；后续代换建立在等值表达上。')
add('U05-O01','百数表里的恒等关系：从发现到说明','68','字母表达；分配与合并','用字母证明一类结构，不把几个例子当普遍证明。','百数表任意完整2×2方块，对角线两个数的和总相等吗？','表格固定的横差1与竖差10决定四个数的关系。','左上写a，右上a+1，左下a+10，右下a+11。','先试21、22、31、32，两对角均53；写一般四格关系；两对角都等于2a+11，所以任意合法方块成立。',('每行8个数的表，完整2×2方块仍有对角和相等吗？','四数a、a+1、a+8、a+9；两对角为a+(a+9)与(a+1)+(a+8)；均2a+9。','相等。'),['百数表左上34，其余三格？|35、44、45|横加1，竖加10。','这四格对角和各多少？|79|34+45=35+44。','左上在一行最后一格，还能照搬2×2吗？|不能|它右边不在同一行。','每行6数，左上a，右下是什么？|a+7|向右1向下6。','百数表2×2四格和能是100吗？|不能|和4a+22除4余2，100除4余0。','检验3个方块与一般证明有何区别？|前者提供线索，后者说明所有合法方块|字母保留结构。'],('试过几个例子就证明永远成立。','需要说出每一个方块共有的结构与等值推理。'),'为什么把左上数换成任何合法a，证明都不需要改变？','思想索引：找不变量、字母表示；不另设一门百数表重复课。')

unit('U10','混版衔接：等式与简易方程','55–71','新增必要桥接，不冒充当前PDF单元。安排在U05之后；基础需要补齐，已有掌握证据可直接做E04迁移。')
add('U10-E01','等号两边一样多：怎样改变还保持相等？','58','等量关系；字母表达','理解等式性质与方程的含义。','天平左边一盒珠子和3颗，右边11颗，怎样知道盒内有几颗？','未知量也可参与等量关系；两边做同样可逆操作便不破坏原相等。','天平两侧各取走3颗，剩盒子与8颗平衡。','写x+3=11，等号表示数量相等；两边同减3得到x=8；方程是含未知数的等式，等式不一定都是方程。',('3个同样盒子共重12千克，每盒多重？','写3x=12；两边均分3份；x=4并检查3×4=12。','4千克。'),['x+5=14，两边同时减什么？|5|去掉共同的5。','3x=18，两边同时除什么？|3|每边均分3份。','x+4>9是方程吗？|不是|它不是等式。','7+8=15是方程吗？|不是|没有未知数。','等式两边能同时除0吗？|不能|除以0无意义。','为什么不能左边减3右边减2？|两边差改变|原先相等不再保证。'],('等号表示“接下来写答案”。','等号表达左右值相等；任何一步都要维持这个关系。'),'天平两边同减3，为什么盒子里的珠子没有变化？','下一课系统区分未知加数、被减数与减数。','混版必要桥接：取U05字母与数量关系为先修；当前PDF未以简易方程单元主教，本课原创补齐。')
add('U10-E02','解一步方程：未知数的位置影响做法','58','等式性质；加减乘除关系','用等式性质解一步方程并代入检验，覆盖未知减数与除数。','有20张卡，送出x张后剩7张，x该怎样求？','方程保留原来的问题方向，解方程反向找符合等量条件的数。','20格长条，左段x、右段7；与x+7=20等值。','20-x=7可两边加x再减7，得x=13；x÷4=3两边乘4；12÷x=3先说明x≠0，再得12=3x。',('解18÷x=6。','x不能为0；两边乘x得18=6x；两边除6得x=3，代回18÷3=6。','x=3。'),['x+6=15，求x。|9|两边减6。','x-6=15，求x。|21|两边加6。','21-x=9，求x。|12|21=9+x。','4x=14，求x。|3.5|两边除4。','x÷0.5=8，求x。|4|两边乘0.5，不是除0.5。','用x=12检查21-x=9。|21-12=9，成立|代入原方程。'],('未知数在减号后也直接“减掉右边”。','先辨认数量角色或按等式性质推导，不背不分位置的口令。'),'21-x=9与x-21=9为什么解不同？','进入两步方程：先处理整组再处理每份。','混版必要桥接；不称为该PDF的原练习。')
add('U10-E03','两步方程：把一整组看清再拆开','64','一步方程；括号与分配律','解ax+b=c和a(x+b)=c，区分括号整体。','每盒彩笔x元，买3盒另付2元袋费，总共20元，如何列式？','3x是三盒总价，2是只收一次的袋费；括号会改变重复的范围。','画3段x再接2，与总长20对齐；另一图画3段(x+2)。','3x+2=20先两边减2，再除3；3(x+2)=20先除3再减2；把得到的x带回原情境检验。',('解4(x+1.5)=22。','两边除4，x+1.5=5.5；两边减1.5，x=4；4×(4+1.5)=22。','x=4。'),['2x+3=13，求x。|5|先减3再除2。','2(x+3)=14，求x。|4|先除2再减3。','5x-4=16，求x。|4|先加4再除5。','3盒同价笔加2元袋费共17元，每盒多少？|5元|3x+2=17。','3(x+2)=3x+2对吗？|错，应3x+6|括号内2重复3次。','解完x=5，只检查最后一步够吗？|不够，应代入原式|原列式或变形也可能错。'],('见到3(x+2)就先用右边减2。','3乘的是整个括号，先把整组数求出更清楚。'),'一次袋费与每盒都有袋费，在式子里差在哪？','下一课先建数量关系，再选择算术或方程。','混版必要桥接；两步方程为后续分数应用的先修。')
add('U10-E04','方程解决问题：两种量先写成同一种未知量','64','两步方程；字母倍数表示','用同一未知量表示关联数量，解释和倍、差倍结构。','长绳是短绳的3倍，两绳共32米，各多长？','用短绳作1份，长绳就是3份，总量化成4份，方程与线段图表达同一结构。','画短绳1段x，长绳3段x，外框标32。','设短绳x米，长绳3x米；x+3x=32，合成4x=32；求得8与24，检查和32及倍数3都满足。',('两盒卡片共45张，大盒比小盒多9张，各几张？','设小盒x，大盒x+9；x+(x+9)=45；2x=36，x=18，大盒27。','小盒18张，大盒27张。'),['长绳2x、短绳x，合计怎样写？|3x|同量相加。','甲x、乙4x，乙比甲多多少？|3x|4份减1份。','两数和40、差6，较小数？|17|2x+6=40。','两数差18，大数4倍于小数，求小数。|6|4x-x=18。','共32且3倍关系，只检查8+24=32够吗？|不够|还须24=3×8。','和倍问题需要背新公式吗？|不需要，画份数或列方程|用同一结构推导。'],('大数是小数3倍，差也是3倍。','差为3份减1份，剩2份。'),'画线段与写x+3x=32哪里一一对应？','代换与消元作为本桥接的可选思想提升。','混版必要桥接；和差、和倍不是重开题型课，是已学数量结构的方程迁移。')
add('U10-O01','代换与消元：换掉的是等量关系','64','等式性质；合并同类量；两步方程','通过等价替换或两条关系相减消去共同量。','1本本子加1支笔共7元，1本本子加3支同款笔共13元，能先知道什么？','两次购买共有同一本子，相减后只留下多出的2支笔。','两条价钱条上下对齐，共同本子部分划去，剩两支笔对应6元。','13-7=6是2支笔差额，单支3元；7-3=4是本子价；把两种价格带回两次购物同时检验。',('1盒点心价等于2杯果汁；1盒点心加1杯果汁共18元，各多少钱？','用2杯果汁替换点心；3杯共18，每杯6；点心12，检验12+6=18。','果汁6元，点心12元。'),['x+y=10，x+2y=14，y是多少？|4|相减剩y。','上题x是多少？|6|10-4。','若两条式子共同的量不同，还能直接划掉吗？|不能|必须是完全相同的数量。','1袋米=3袋豆的价，米豆各1袋共28元，豆价？|7元|代换为4袋豆。','2x+y=15、x+y=9，求x、y。|x=6，y=3|相减得x，再代回。','为什么得到两个价格后要检查两次购买？|两条条件都必须成立|满足一条不保证另一条。'],('图形长得一样，就能随便消去。','能消去的是数值相等且在两边相应运算位置一致的量。'),'“消消乐”里真正被消掉的是什么？','未来初中系统学方程组；本课只做具体数量的等量推理。','独立思想索引O；依托本章字母和桥接方程，不冒充五上课本原章。')
